import{_ as e,o,c as a,a2 as i}from"./chunks/framework.DaAAbehN.js";const m=JSON.parse('{"title":"Lesson 3: Codex vs Other Tools (No Overthinking Version)","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-1/lesson-3.md","filePath":"en/modules/module-1/lesson-3.md"}'),n={name:"en/modules/module-1/lesson-3.md"};function r(s,t,l,d,h,u){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="lesson-3-codex-vs-other-tools-no-overthinking-version" tabindex="-1">Lesson 3: Codex vs Other Tools (No Overthinking Version) <a class="header-anchor" href="#lesson-3-codex-vs-other-tools-no-overthinking-version" aria-label="Permalink to &quot;Lesson 3: Codex vs Other Tools (No Overthinking Version)&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Understand the differences between Codex, ChatGPT, and GitHub Copilot, and know when to use which tool ⏱️ <strong>Estimated Time</strong>: 10 minutes 🎯 <strong>Teaching Rhythm</strong>: Comparison-focused explanation</p></blockquote><hr><h2 id="i-the-bottom-line-up-front" tabindex="-1">I. The Bottom Line Up Front <a class="header-anchor" href="#i-the-bottom-line-up-front" aria-label="Permalink to &quot;I. The Bottom Line Up Front&quot;">​</a></h2><p>If you only remember one sentence from this lesson, let it be this:</p><blockquote><p><strong>Codex can do far more than a regular chat AI — it can directly operate files on your computer.</strong></p></blockquote><p>We&#39;ll go into the other details gradually.</p><hr><h2 id="ii-codex-vs-chatgpt" tabindex="-1">II. Codex vs ChatGPT <a class="header-anchor" href="#ii-codex-vs-chatgpt" aria-label="Permalink to &quot;II. Codex vs ChatGPT&quot;">​</a></h2><h3 id="relationship-explained" tabindex="-1">Relationship Explained <a class="header-anchor" href="#relationship-explained" aria-label="Permalink to &quot;Relationship Explained&quot;">​</a></h3><p>Codex is <strong>built into</strong> ChatGPT. That means:</p><ul><li>When you use ChatGPT and switch to &quot;Advanced Search&quot; or &quot;Code Interpreter&quot; mode, you&#39;re using Codex</li><li>The standalone Codex desktop app you download is essentially ChatGPT&#39;s Codex feature, just with a better interface</li></ul><p><strong>Simple analogy</strong>: ChatGPT is a car, and Codex is that car&#39;s &quot;autonomous driving mode.&quot;</p><table tabindex="0"><thead><tr><th>Feature</th><th>ChatGPT (Regular Chat Mode)</th><th>Codex (Code Interpreter / Advanced Search Mode)</th></tr></thead><tbody><tr><td>Primary capability</td><td>Answering questions, writing copy, translating</td><td>Reading files, writing code, running commands, File Operations</td></tr><tr><td>Can it operate your files?</td><td>❌ No</td><td>✅ Yes (within the workspace)</td></tr><tr><td>Can it execute code?</td><td>❌ No</td><td>✅ Yes</td></tr><tr><td>Typical use case</td><td>&quot;Help me write an email&quot;</td><td>&quot;Help me analyze this Excel file&quot;</td></tr></tbody></table><h3 id="one-thing-for-beginners-to-remember" tabindex="-1">One thing for beginners to remember: <a class="header-anchor" href="#one-thing-for-beginners-to-remember" aria-label="Permalink to &quot;One thing for beginners to remember:&quot;">​</a></h3><ul><li>Want to <strong>chat, ask questions, write copy</strong> → Use ChatGPT regular mode</li><li>Want to <strong>have AI do work for you</strong> (File Operations, write code, do analysis) → Use Codex</li></ul><hr><h2 id="iii-codex-vs-github-copilot" tabindex="-1">III. Codex vs GitHub Copilot <a class="header-anchor" href="#iii-codex-vs-github-copilot" aria-label="Permalink to &quot;III. Codex vs GitHub Copilot&quot;">​</a></h2><p>This is the pair most people confuse.</p><h3 id="what-is-github-copilot" tabindex="-1">What is GitHub Copilot? <a class="header-anchor" href="#what-is-github-copilot" aria-label="Permalink to &quot;What is GitHub Copilot?&quot;">​</a></h3><p>Copilot is a <strong>code completion plugin</strong> that runs inside your code editor (like VS Code).</p><ul><li>As you type code, it guesses what you want to write and completes the next line</li><li>It <strong>cannot</strong> complete tasks independently — you must write the code yourself, debug it, and test it</li><li>It <strong>cannot</strong> operate your files — it can only give you suggestions inside the editor</li></ul><h3 id="what-is-codex" tabindex="-1">What is Codex? <a class="header-anchor" href="#what-is-codex" aria-label="Permalink to &quot;What is Codex?&quot;">​</a></h3><p>Codex is a <strong>standalone intelligent agent</strong>.</p><ul><li>You tell it &quot;help me build a webpage,&quot; and it reads files, writes code, and saves files on its own</li><li>It <strong>can</strong> independently complete the entire process from requirement to delivery</li><li>It <strong>can</strong> operate your file system</li></ul><h3 id="comparison-table" tabindex="-1">Comparison Table <a class="header-anchor" href="#comparison-table" aria-label="Permalink to &quot;Comparison Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>GitHub Copilot</th><th>Codex</th></tr></thead><tbody><tr><td>Where it works</td><td>Inside code editor (VS Code, etc.)</td><td>Standalone app / command line</td></tr><tr><td>Do you need to know how to code?</td><td>✅ Yes, at least read code</td><td>❌ No, use natural language</td></tr><tr><td>Task granularity</td><td>Single line / single function completion</td><td>Complete features / complete projects</td></tr><tr><td>Can it do File Operations?</td><td>❌ No</td><td>✅ Yes</td></tr><tr><td>Can it run code?</td><td>❌ No</td><td>✅ Yes</td></tr><tr><td>Typical user</td><td>Programmers</td><td>Anyone</td></tr></tbody></table><h3 id="one-thing-for-beginners-to-remember-1" tabindex="-1">One thing for beginners to remember: <a class="header-anchor" href="#one-thing-for-beginners-to-remember-1" aria-label="Permalink to &quot;One thing for beginners to remember:&quot;">​</a></h3><ul><li><strong>Copilot = &quot;co-pilot&quot; that helps you complete code</strong></li><li><strong>Codex = &quot;intern&quot; that helps you complete entire tasks</strong></li></ul><hr><h2 id="iv-codex-vs-traditional-automation-tools" tabindex="-1">IV. Codex vs Traditional Automation Tools <a class="header-anchor" href="#iv-codex-vs-traditional-automation-tools" aria-label="Permalink to &quot;IV. Codex vs Traditional Automation Tools&quot;">​</a></h2><p>You may have heard of RPA (Robotic Process Automation), Excel macros, Apple Shortcuts, and similar tools.</p><h3 id="problems-with-traditional-automation-tools" tabindex="-1">Problems with traditional automation tools <a class="header-anchor" href="#problems-with-traditional-automation-tools" aria-label="Permalink to &quot;Problems with traditional automation tools&quot;">​</a></h3><ul><li>They require you to <strong>design the workflow in advance</strong>, which is inflexible</li><li>When requirements change, you have to reconfigure everything</li><li>They usually require programming knowledge or specialized tools</li></ul><h3 id="codex-s-advantages" tabindex="-1">Codex&#39;s advantages <a class="header-anchor" href="#codex-s-advantages" aria-label="Permalink to &quot;Codex&#39;s advantages&quot;">​</a></h3><ul><li><strong>Describe your needs in natural language</strong> — no need to design workflows in advance</li><li><strong>Flexible adjustments</strong> — if something doesn&#39;t look right, just tell Codex to fix it</li><li><strong>No programming knowledge needed</strong></li></ul><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Task</th><th>Traditional Way</th><th>Codex Way</th></tr></thead><tbody><tr><td>Batch rename files</td><td>Write a Python script, or use dedicated batch rename software</td><td>Just say: &quot;Change &#39;IMG_&#39; to &#39;Photo_&#39; in all these filenames&quot;</td></tr><tr><td>Merge multiple Excels</td><td>Use Power Query or VBA</td><td>Just say: &quot;Merge the data from these three Excel files into one sheet&quot;</td></tr></tbody></table><hr><h2 id="v-one-sentence-summary-for-this-section" tabindex="-1">V. One-Sentence Summary for This Section <a class="header-anchor" href="#v-one-sentence-summary-for-this-section" aria-label="Permalink to &quot;V. One-Sentence Summary for This Section&quot;">​</a></h2><blockquote><p><strong>Codex is not a chat tool, not a code completion tool, and not a traditional automation tool. It&#39;s a smart assistant that understands natural language and can operate your computer.</strong></p></blockquote><hr><h2 id="vi-post-lesson-thinking" tabindex="-1">VI. Post-Lesson Thinking <a class="header-anchor" href="#vi-post-lesson-thinking" aria-label="Permalink to &quot;VI. Post-Lesson Thinking&quot;">​</a></h2><ol><li>What tools have you used before to try automating office work? How is Codex different?</li><li>In what scenarios would you choose Codex over other tools?</li></ol><hr><h2 id="vii-next-step" tabindex="-1">VII. Next Step <a class="header-anchor" href="#vii-next-step" aria-label="Permalink to &quot;VII. Next Step&quot;">​</a></h2><p><a href="./../module-2/lesson-4.html">→ Enter Module 2: Getting Started</a></p>',47)])])}const p=e(n,[["render",r]]);export{m as __pageData,p as default};
